local config = {
  ui_story_31120101_1_dialog_content = "(Estoy muy disgustado ahora mismo, y esta es la razón...)",
  ui_story_31120101_2_dialog_content = "(Tiránica, fría, sin corazón, hace lo que quiere sin preocuparse por los demás...)",
  ui_story_31120101_2X_dialog_content = "(Se podría escribir una novela con todos los rasgos negativos que la describen).",
  ui_story_31120101_3_dialog_content = "Desde que Smokey empezó a vivir en el Colossus, la opinión de todos sobre ella ha ido empeorando.",
  ui_story_31120101_4_dialog_content = "Últimamente se han presentado muchas quejas contra ella debido a su temperamento.",
  ui_story_31120101_5_dialog_content = "Tienes razón, incluso Soroz la ha denunciado por dejar huellas carbonizadas por todas partes. También ha sido muy duro para nuestro querido Colossus.",
  ui_story_31120101_6_dialog_content = "Para solucionar estos problemas, algunas personas han propuesto una solución.",
  ui_story_31120101_7_dialog_content = "Esa sería mi sugerencia... Lo llamo “Operación: Mejorar la imagen de Smokey\".",
  ui_story_31120101_8_dialog_content = "Le agradecería cualquier ayuda que pueda darme.",
  ui_story_31120101_9_dialog_content = "Smokey puede parecer muy mala, pero en verdad es una persona muy agradable.",
  ui_story_31120101_10_dialog_content = "Por eso quiero ayudar a todos a entender sus buenas cualidades, también...",
  ui_story_31120101_11_dialog_content = "¿Y tal vez podríamos recordarle gentilmente que trate de llevarse bien con todos en el Colossus?",
  ui_story_31120101_12_dialog_content = "Soy más joven que ella, así que no creo que tenga derecho a hacerlo. Pero como PlayerName está a cargo del Colossus...",
  ui_story_31120101_13_dialog_content = "¡En ese caso, parece que esta parte de la misión te corresponde a ti, PlayerName!",
  ui_story_31120101_14_dialog_content = "Areia y yo proporcionaremos apoyo en secreto. Smokey debería estar en el Café. ¡Adelante!",
  ui_story_31120101_15_dialog_content = "¿Eh? ¿A-ahora? ¡Pero todavía no sé qué hacer!",
  ui_story_31120101_15X_dialog_content = "Está bien, creemos en ti. ¡Ahora vete!",
  ui_story_31120101_16_dialog_content = "<color=#e8d9bb>Silbido... Silbido...</color>",
  ui_story_31120101_17_dialog_content = "<size=30>Otra vez ella no... Mira, el suelo está todo quemado ahora...</size>",
  ui_story_31120101_18_dialog_content = "¡Muévete! A menos que quieras quemarte bajo mis pies, sal de mi vista.",
  ui_story_31120101_19_dialog_content = "Oye, ¿qué estás mirando, PlayerName? ¿No tienes nada que hacer?",
  ui_story_31120101_20_dialog_content = "¡Nada, Smokey! No me hagas caso, sólo estoy aquí para tomar un descanso...",
  ui_story_31120101_21_dialog_content = "Ahem... ¿Disculpa, Smokey? ¿Podría ayudarme con algo?",
  ui_story_31120101_22_dialog_content = "(Entiendo... Ella está tratando de mostrar a todos cómo acercarse a Smokey)",
  ui_story_31120101_23_dialog_content = "(¡Si acepta ayudar, puedo elogiarla por echar una mano! Entonces todos deberían...)",
  ui_story_31120101_24_dialog_content = "Nop.",
  ui_story_31120101_25_dialog_content = "¿Eh? ¿N-No puedes? Es decir, probablemente no sea nada demasiado problemático, así que ¿por qué no escuchar primero a Vice?",
  ui_story_31120101_26_dialog_content = "Entonces escúpelo. No tengo todo el día.",
  ui_story_31120101_27_dialog_content = "En verdad, es para Areia, no para mí. Ustedes son muy cercanos, ¿verdad?",
  ui_story_31120101_28_dialog_content = "¿Smokey? ¿Podrías ayudarme a llevar algunas flores al salón? Si quiero...",
  ui_story_31120101_29_dialog_content = "(Espera... ¡Ahora veo su estrategia! La están haciendo decorar el salón con flores con el pretexto de ayudar).",
  ui_story_31120101_30_dialog_content = "(Después, si alguien pregunta, sabrá que fue Smokey quien las puso allí)",
  ui_story_31120101_31_dialog_content = "(Es un poco infantil, cierto... Pero tiene el nombre de Areia escrito por todas partes. Mientras Smokey esté de acuerdo...)",
  ui_story_31120101_32_dialog_content = "No. Tengo otras cosas que hacer, Areia.",
  ui_story_31120101_33_dialog_content = "Ahem... No creo que Areia quiera decir que te ayudaré ahora, quizás cuando tengas algo de tiempo libre...",
  ui_story_31120101_34_dialog_content = "Ya que tienes tanto que decir al respecto, PlayerName, ¿por qué no les ayudas? Repartir flores no es lo mío.",
  ui_story_31120101_35_dialog_content = "<size=30>Eso fue demasiado, no crees... Cómo puede alguien ser tan frío...</size>",
  ui_story_31120101_36_dialog_content = "<size=30>¡Shh, no tan fuerte! Vamos a casa...</size>",
  ui_story_31120101_37_dialog_content = "Pero ya llevas mucho tiempo sentado en el Café, Smokey. Sólo pensé que no estabas ocupado...",
  ui_story_31120101_38_dialog_content = "No asumas.",
  ui_story_31120101_39_dialog_content = "B-Bien. Lo siento...",
  ui_story_31120101_39X1_dialog_content = "¡No te molesto más, entonces... <size=30>Buena suerte, PlayerName</size>. Adiós...",
  ui_story_31120101_39X2_dialog_content = "...",
  ui_story_31120101_40_option_content = "(Debería ser sincero con ella en todo...)",
  ui_story_31120101_41_dialog_content = "Smokey... Asustaste a todos en el Café. Están empezando a quejarse de tu comportamiento...",
  ui_story_31120101_41X_dialog_content = "<size=30>Para ser honesto, sólo estábamos tratando de ayudarte a mejorar tu imagen...</size>",
  ui_story_31120101_42_option_content = "(Debería pensar en otro enfoque...)",
  ui_story_31120101_43_dialog_content = "No deberías haber rechazado a Areia de esa manera, Smokey. Creo que has herido sus sentimientos...",
  ui_story_31120101_44_dialog_content = "Realmente no tienes nada más que hacer, ¿eh?",
  ui_story_31120101_45_dialog_content = "No es eso, resulta que tengo algo de tiempo libre ahora mismo...",
  ui_story_31120101_46_dialog_content = "De acuerdo, ya que no tienes nada mejor que hacer, ¡entonces ven conmigo!",
  ui_story_31120101_47_dialog_content = "¿Eh? Pero no he terminado de hablar... ¡O-Oye! ¡Suelta mi cuello! ¿A dónde vamos?",
  ui_story_31120101_48_dialog_content = "Umbraton ¡A buscar un tesoro!",
  ui_story_31120101_49_dialog_content = "*Tos* Tú... Casi me ahogas hasta la muerte...",
  ui_story_31120101_50_dialog_content = "Deja de exagerar. Ahora recupere el aliento, y recupérese.",
  ui_story_31120101_51_dialog_content = "Yo... No tendría que recuperar el aliento... si alguien no me estrangulara durante todo el camino...",
  ui_story_31120101_52_dialog_content = "Ya está bien, caramba. ¿Ya te sientes mejor? ¿Crees que puedes ahora?",
  ui_story_31120101_53_dialog_content = "Si, estoy bien ahora... ¿Pero puedes decirme por qué me arrastraste hasta aquí, en primer lugar?",
  ui_story_31120101_54_dialog_content = "Espera.",
  ui_story_31120101_55_dialog_content = "¿Qué...? Si vas a arrastrar a alguien aquí, lo menos que podrías hacer es dar una razón...",
  ui_story_31120101_56_dialog_content = "Cállate. Espera un segundo.",
  ui_story_31120101_57_dialog_content = "¡Smokey! ¡Es Smokey! ¿Qué estás haciendo acá?",
  ui_story_31120101_58_dialog_content = "Sólo pasaba por aquí, eso es todo.",
  ui_story_31120101_58X_dialog_content = "¡Mira, Smokey! ¡Recogí algunas flores hoy temprano! ¡Toma, coge una!",
  ui_story_31120101_58X1_dialog_content = "No quiero flores.",
  ui_story_31120101_59_dialog_content = "Ah... E-Está bien...",
  ui_story_31120101_60_dialog_content = "Parece herida, Smokey... ¿Por qué no la tomas? Es sólo una flor...",
  ui_story_31120101_61_dialog_content = "No puedo. Tengo otros asuntos que tratar. Vamos, PlayerName.",
  ui_story_31120101_61X_dialog_content = "Oye, no te quedes hasta muy tarde, o tu madre se preocupará.",
  ui_story_31120101_62_dialog_content = "O-Okay, Smokey. ¡Hasta luego!",
  ui_story_31120101_63_dialog_content = "Debe haber un par de Eclipsites merodeando por aquí. Encuéntralos.",
  ui_story_31120101_64_dialog_content = "¿Ah?",
  ui_story_31120101_65_dialog_content = "¿No fui claro? Tienes habilidades psíquicas, ¿verdad? Dime, ¿puedes sentir algún Eclipsites cerca y, si es así, dónde están?",
  ui_story_31120101_66_dialog_content = "Eclipsites... Parece que hay bastantes en esa dirección.",
  ui_story_31120101_67_dialog_content = "Bien, ¡vamos!",
  ui_story_31120101_68_dialog_content = "¡¿Eh?! ¡N-no mi collar, otra vez!",
  ui_story_31120101_69_dialog_content = "Están justo delante. Deberíamos estar bien, siempre y cuando no carguemos hacia ellos.",
  ui_story_31120101_70_dialog_content = "Bien, bien hecho. Como recompensa, te dejaré que me cuentes lo que estabas tramando los tres.",
  ui_story_31120101_71_dialog_content = "Ese truco en el Café... ¿Qué estabas tratando de decirme?",
  ui_story_31120101_72_dialog_content = "Así que ya nos descubriste, ¿eh? En verdad, desde que llegaron al Colossus...",
  ui_story_31120101_73_dialog_content = "La mayoría de la gente a bordo se ha llevado una mala impresión de ti, pero Areia insiste en que eres una buena persona.",
  ui_story_31120101_74_dialog_content = "Ella quería que todos se dieran cuenta, también... Así que nos pidió ayuda a Vice y a mí para mejorar tu imagen.",
  ui_story_31120101_75_dialog_content = "¡Ja! ¿Ser una buena persona es tan importante para todos? Bien, no seré más duro con ellos.",
  ui_story_31120101_76_dialog_content = "Sólo queríamos ayudarte a llevarte bien con todo el mundo...",
  ui_story_31120101_76X_dialog_content = "Hmph. Al menos puedo distinguir la diferencia entre ser tratado como una persona y ser tratado como un Eclipsite.",
  ui_story_31120101_76X1_dialog_content = "¡¿Qué se supone que significa eso?! Todo el mundo puede hacer esa distinción, ¿verdad?",
  ui_story_31120101_76X2_dialog_content = "Siento que te estás perdiendo el punto de la idea de Areia...",
  ui_story_31120101_77_dialog_content = "No, lo entiendo bien. ¿He esperado tanto tiempo por ti, pero resulta que estabas planeando algo así todo el tiempo?",
  ui_story_31120101_78_dialog_content = "Eh... Esa no parece la cara de alguien que entiende...",
  ui_story_31120101_78X_dialog_content = "Además, no recuerdo haber accedido a verte hoy.",
  ui_story_31120101_79_dialog_content = "No lo hiciste. Vine a buscarte para llevarte a cazar Eclipsites.",
  ui_story_31120101_79X_dialog_content = "Parecías muy ocupado, así que esperé todo el día para pillarte en un descanso.",
  ui_story_31120101_80_dialog_content = "¡Gaaah!",
  ui_story_31120101_81_dialog_content = "Ya que nos encontraste, ¡parece que tendré que ponerlos a todos en sus lugares! ¡Ven!",
  ui_story_31120101_82_dialog_content = "¡Graagh!",
  ui_story_31120101_83_dialog_content = "Tch... Aquí tampoco.",
  ui_story_31120101_84_dialog_content = "Nos movemos al siguiente lugar, PlayerName. ¿Dónde están los otros Eclipsites?",
  ui_story_31120101_85_dialog_content = "¿Qué tramas exactamente, Smokey?",
  ui_story_31120101_86_dialog_content = "Buscando un collar. ¡Se me cayó la maldita cosa en una turba de Eclipsites!",
  ui_story_31120101_87_dialog_content = "Buscando un collar... ¿A eso te referías con tener otras cosas que hacer?",
  ui_story_31120101_88_dialog_content = "Ahora te estás dando cuenta. ¡Vamos, encuentra nuestra próxima parada!",
  ui_story_31120101_89_dialog_content = "¡Está bien, está bien! Sólo deja de tirar de mí por el cuello...",
  ui_story_31120101_90_dialog_content = "¡Graagh!",
  ui_story_31120101_91_dialog_content = "No tengo todo el día, así que ven a mí de una vez.",
  ui_story_31120101_92_dialog_content = "*Rugido*",
  ui_story_31120101_92X_dialog_content = "¡Cállate, ya!",
  ui_story_31120101_93_dialog_content = "Ugh...",
  ui_story_31120101_94_dialog_content = "¡Ugh, tampoco está aquí!",
  ui_story_31120101_95_option_content = "Eres muy fuerte...",
  ui_story_31120101_96_dialog_content = "¿Qué? ¿Tienes miedo o algo así?",
  ui_story_31120101_97_dialog_content = "¡Para nada! De hecho, me siento muy seguro.",
  ui_story_31120101_98_dialog_content = "¡Ja, es un rumor interesante! Una pena que otras personas no sientan lo mismo, ¿eh?",
  ui_story_31120101_99_option_content = "Tus zapatos están en llamas...",
  ui_story_31120101_100_dialog_content = "¿Qué? ¿Tienes un problema con eso?",
  ui_story_31120101_101_dialog_content = "Bueno, algo así... He oído que has estado dejando marcas quemadas por todo el Colossus...",
  ui_story_31120101_102_dialog_content = "¿Todavía están bien tus zapatos?",
  ui_story_31120101_103_dialog_content = "¡Ja, ahora es una pregunta interesante. Relájate, están hechos de un material especial.",
  ui_story_31120101_104_dialog_content = "¿Crees que esa es la razón por la que no puedo llevarme bien con los demás?",
  ui_story_31120101_105_dialog_content = "¿P-por qué me preguntas eso, de repente?",
  ui_story_31120101_106_dialog_content = "Estás pensando que podría saber la respuesta a esa pregunta, ¿verdad?",
  ui_story_31120101_106X_dialog_content = "Adelante, dime: ¿por qué es tan difícil llevarse bien conmigo?",
  ui_story_31120101_107_dialog_content = "Bien...",
  ui_story_31120101_108_option_content = "Lo más importante es tu temperamento, ¡te calientas con demasiada facilidad!",
  ui_story_31120101_109_dialog_content = "¿Oh? ¿Quieres decir ASÍ?",
  ui_story_31120101_110_option_content = "Lo más importante es que no eres tan accesible.",
  ui_story_31120101_111_dialog_content = "¿Oh? ¿Qué te parece esto? ¿Aún piensas que soy inaccesible?",
  ui_story_31120101_112_dialog_content = "¡¿Flamas?!",
  ui_story_31120101_113_dialog_content = "¡Relájate, no te quemará! <size=40>¡Abajo!</size>",
  ui_story_31120101_114_dialog_content = "*Rugido*",
  ui_story_31120101_115_dialog_content = "Un ataque furtivo, ¿eh? No hay dados, cobardes.",
  ui_story_31120101_116_dialog_content = "Lo s-siento... No estaba prestando atención.",
  ui_story_31120101_117_dialog_content = "Está bien.",
  ui_story_31120101_117X_dialog_content = "¡Ja, lo encontré!",
  ui_story_31120101_117X1_dialog_content = "Vamos, regresemos..",
  ui_story_31120101_118_dialog_content = "¿Smokey? ¿Qué estás haciendo acá?",
  ui_story_31120101_119_dialog_content = "Toma, esto es de tu madre. Cuídalo bien, y no lo pierdas de nuevo.",
  ui_story_31120101_120_dialog_content = "Esto es... ¡El collar de mamá! Smokey, ¿cómo...?",
  ui_story_31120101_121_dialog_content = "Lo encontré tirado en el camino.",
  ui_story_31120101_122_dialog_content = "¡Muchas gracias, Smokey! Pero qué debería darte...",
  ui_story_31120101_123_dialog_content = "Tenías una flor para mí antes, ¿verdad? Entrégala.",
  ui_story_31120101_124_dialog_content = "<size=30>No sólo tomaste la flor de antes, sino que también le diste la oportunidad de devolver un favor...</size>",
  ui_story_31120101_124X_dialog_content = "<size=30>Lo que hiciste fue muy considerado... Pero, ¿por qué le pides esa flor como si la estuvieras robando?</size>",
  ui_story_31120101_125_dialog_content = "Así es como hago las cosas.",
  ui_story_31120101_126_dialog_content = "¡Muchas gracias, Smokey! Toma, recogí esta flor por la mañana. No está tan fresca como antes, pero si la sostienes muy cerca, ¡huele increíble!",
  ui_story_31120101_126X_dialog_content = "¿No te quedas a beber un poco de agua?",
  ui_story_31120101_126X1_dialog_content = "Mamá debería llegar pronto a casa, ¡y estoy seguro de que le encantaría darte las gracias en persona!",
  ui_story_31120101_127_dialog_content = "Sostén esto, PlayerName.",
  ui_story_31120101_127X_dialog_content = "¡Nos vamos! ¡Nos vemos!",
  ui_story_31120101_128_dialog_content = "¿Ah? Okay... ¡Adiós, Smokey!",
  ui_story_31120101_129_dialog_content = "¿Eh? ¡E-Espera Smokey! No puedes irte así... ¿Smokey?",
  ui_story_31120101_130_dialog_content = "No te preocupes, pequeña. No está molesta ni nada, sólo... tiene otras cosas que hacer.",
  ui_story_31120101_131_dialog_content = "Parece que no podemos quedarnos hoy, lo siento.",
  ui_story_31120101_132_dialog_content = "¡Oh, no pasa nada! Smokey siempre ha sido así, especialmente cuando es hora de irse.",
  ui_story_31120101_132X_dialog_content = "Me ayudarás a llevarle su flor, ¿verdad?",
  ui_story_31120101_132X1_dialog_content = "¡Seguro! No te preocupes, encontraré la manera de dársela.",
  ui_story_31120101_132X2_dialog_content = "¡Adiós!",
  ui_story_31120101_133_dialog_content = "¡Espérame, Smokey!",
  ui_story_31120101_133X_dialog_content = "Esta flor... Deberías conservarla.",
  ui_story_31120101_134_dialog_content = "Déjame preguntarte algo: ¿crees que soy fuerte?",
  ui_story_31120101_134X_dialog_content = "W... ¿Por qué me preguntas eso de repente?",
  ui_story_31120101_134X1_dialog_content = "Sólo responde a la pregunta.",
  ui_story_31120101_135_dialog_content = "Sí, eres fuerte. Increíblemente fuerte, para ser honesto.",
  ui_story_31120101_136_dialog_content = "¿También crees que soy inaccesible?",
  ui_story_31120101_137_dialog_content = "¿Lo preguntas porque te molesta?",
  ui_story_31120101_138_dialog_content = "Hah, ¿realmente crees que me molesta eso? Entonces te diré...",
  ui_story_31120101_139_dialog_content = "*Exhala* ¿Qué piensas? Caliente, ¿eh?",
  ui_story_31120101_140_dialog_content = "T-Tu aliento... ¡Es como vapor! ¿Por qué está tan caliente?",
  ui_story_31120101_141_dialog_content = "Me he estado sintiendo mal últimamente...",
  ui_story_31120101_141X_dialog_content = "Ha sido difícil para mí apagar las llamas de mi cuerpo.",
  ui_story_31120101_142_dialog_content = "Si te acercas demasiado a mí, existe la posibilidad de que tu ropa se incendie.",
  ui_story_31120101_143_dialog_content = "¿Es esa la razón por la que te negaste a sostener esta flor?",
  ui_story_31120101_144_dialog_content = "Exacto. Cuando recuperes esa flor, todo estará bien.",
  ui_story_31120101_144X_dialog_content = "Un buen final para todos.",
  ui_story_31120101_145_dialog_content = "Areia tenía razón todo el tiempo, tú ERES una buena persona.",
  ui_story_31120101_145X_dialog_content = "Pero aún quiero seguir con nuestro plan para mejorar tu imagen. Quiero que todos lo sepan, también...",
  ui_story_31120101_146_dialog_content = "Vuelve y dile a Areia que no se preocupe tanto por mi imagen. No me importa lo que los demás piensen de mí.",
  ui_story_31120101_146X_dialog_content = "Eso va para ti también. Encuentra otra cosa que hacer con tu tiempo.",
  ui_story_31120101_147_dialog_content = "¡Pero todo el mundo tiene una idea equivocada de ti! Todos piensan que eres una persona temperamental e indiferente...",
  ui_story_31120101_148_dialog_content = "Bueno, tienen razón en una cosa: tengo mal carácter. Además, la gente que debería entenderme ya lo hace.",
  ui_story_31120101_149_dialog_content = "Yo diría que tu pequeño \"plan\" fue un éxito.",
  ui_story_31120101_149X_dialog_content = "¿O es que mi imagen no ha mejorado todavía a tus ojos?",
  ui_story_31120601_1_dialog_content = "(En el cielo nocturno sobre la ciudad...)",
  ui_story_31120601_2_dialog_content = "(Allí, lo que brillaba más contra la oscuridad, incluso más brillante que cualquier estrella en el cielo... era la piedra preciosa en su mano).",
  ui_story_31120601_3_dialog_content = "(No tengo idea de cuándo o cómo logró robarlo).",
  ui_story_31120601_4_dialog_content = "(Pero lo que sí sé, es que cualquiera que viera lo que vi sentiría lo mismo que yo...)",
  ui_story_31120601_5_dialog_content = "(Como si les hubieran robado algo precioso.)",
  ui_story_31120601_6_dialog_content = "<color=#e8d9bb>Antes ese mismo día</color>",
  ui_story_31120601_7_dialog_content = "Entonces, en otras palabras, aceptaste un trabajo para salvaguardar una piedra preciosa preciosa.",
  ui_story_31120601_8_dialog_content = "El propietario de la piedra preciosa recibió una tarjeta de visita de un ladrón fantasma.",
  ui_story_31120601_9_dialog_content = "Y por alguna razón... crees que esto tiene algo que ver con Smokey. ¿Está bien?",
  ui_story_31120601_10_dialog_content = "¡Exactamente! Debería haber sabido que ella caminaría por el camino del crimen tarde o temprano...",
  ui_story_31120601_11_dialog_content = "¡Esta vez, te juro que no dejaré que se salga con la suya!",
  ui_story_31120601_12_dialog_content = "¡La ataré bien fuerte y la haré llorar y suplicar piedad justo a mis pies!",
  ui_story_31120601_13_dialog_content = "Sin embargo, hay una cosa que no entiendo.",
  ui_story_31120601_14_dialog_content = "Aún no has conocido a tu cliente, ¿verdad? Cómo puedes estar tan seguro Smokeyestá involucrado?",
  ui_story_31120601_15_dialog_content = "Llámalo la intuición de una mujer.",
  ui_story_31120601_16_dialog_content = "¿Eso es todo?",
  ui_story_31120601_17_dialog_content = "Es tan simple como eso.",
  ui_story_31120601_18_dialog_content = "Créeme, cuando se trata de cazar Smokey...",
  ui_story_31120601_19_dialog_content = "¡Mi intuición es mucho más aguda que la habilidad psíquica de Caelestite!",
  ui_story_31120601_20_dialog_content = "Ya veo... Entonces, ¿qué tiene que ver todo esto conmigo?",
  ui_story_31120601_21_dialog_content = "Con el fin de ejecutar mi plan impecable para detener y restringir Smokey, ¡usted desempeñará el papel más crucial, Sr. Navegante!",
  ui_story_31120601_22_dialog_content = "¡Ahora vámonos! El tiempo mencionado en la tarjeta de visita se acerca rápidamente.",
  ui_story_31120601_23_dialog_content = "Claro, pero... ¿Crees que al menos podrías aflojar tu látigo primero? Realmente no puedo moverme...",
  ui_story_31120601_24_dialog_content = "Mis disculpas, pero para garantizar la ejecución impecable de mi plan impecable, debes soportarlo un poco más.",
  ui_story_31120601_25_dialog_content = "...",
  ui_story_31120601_26_dialog_content = "¡Por fin estás aquí, milady! ¡Por favor, entre!",
  ui_story_31120601_27_dialog_content = "Er, y este tipo encantador atrapado en tu látigo sería...",
  ui_story_31120601_28_dialog_content = "Ah, sí, este es el Sr. Navigator. Él estará sirviendo como mi asistente hoy.",
  ui_story_31120601_29_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_31120601_30_dialog_content = "Vaya... por fin puedo respirar de nuevo...",
  ui_story_31120601_31_dialog_content = "Señor navegante, permítame presentarle al famoso tasador de gemas que mencioné antes.",
  ui_story_31120601_32_dialog_content = "También resulta ser el cliente de mi asignación actual.",
  ui_story_31120601_33_dialog_content = "Hola.",
  ui_story_31120601_34_dialog_content = "Oh mi. ¿Es tan grave la situación que amerita la ayuda no de uno, sino de dos especialistas? Parece que este ladrón fantasma no debe tomarse a la ligera...",
  ui_story_31120601_35_dialog_content = "Tenga la seguridad, buen señor. Conmigo en el caso, el ladrón nunca tendrá éxito.",
  ui_story_31120601_36_dialog_content = "Ahora, ¿podría mostrarme la tarjeta de visita del ladrón?",
  ui_story_31120601_37_dialog_content = "T-Todos se han ido...",
  ui_story_31120601_38_dialog_content = "¿Desaparecido? ¿Qué quieres decir?",
  ui_story_31120601_39_dialog_content = "Recibí la primera tarjeta telefónica hace diez días.",
  ui_story_31120601_40_dialog_content = "Sin embargo, las historias de ladrones fantasmas han estado de moda en Umbraton últimamente.",
  ui_story_31120601_41_dialog_content = "Los niños de hogares sin dinero han estado idolatrando a los ladrones en estas historias y dejando tarjetas de visita como bromas.",
  ui_story_31120601_42_dialog_content = "en lugar de gastar su tiempo en mejores obras.",
  ui_story_31120601_43_dialog_content = "Todos en esta calle que tienen algo a su favor han recibido al menos una tarjeta toscamente hecha de esos pequeños mocosos.",
  ui_story_31120601_44_dialog_content = "Pero a pesar de lo molestos que son, los niños solo están jugando. No son lo suficientemente audaces como para tomar medidas.",
  ui_story_31120601_45_dialog_content = "Entonces, cuando recibí mi primera tarjeta de visita, la descarté como una broma sin pensarlo dos veces.",
  ui_story_31120601_46_dialog_content = "¿Así que simplemente lo tiraste? ¡Esa fue una prueba crucial!",
  ui_story_31120601_47_dialog_content = "Sí... Tiré la primera tarjeta de visita.",
  ui_story_31120601_48_dialog_content = "Pero poco después, recibí otro, seguido de otro más. Había un total de cinco tarjetas telefónicas, todas las cuales mencionaban algo sobre una cuenta regresiva...",
  ui_story_31120601_49_dialog_content = "Decidí salvarlos con la intención de descifrar algún día al cretino que necesitaba un poco de disciplina.",
  ui_story_31120601_50_dialog_content = "¿Y entonces?",
  ui_story_31120601_51_dialog_content = "Y luego... Hace solo tres noches, de repente noté un olor acre a humo en algún lugar de mi habitación...",
  ui_story_31120601_52_dialog_content = "Abrí la puerta, ¡solo para descubrir que la caja donde guardaba las tarjetas de visita se había incendiado!",
  ui_story_31120601_53_dialog_content = "Y allí, de pie junto a él, estaba una figura de físico delgado, cuyo cabello estaba atado en dos largas colas de caballo.",
  ui_story_31120601_54_dialog_content = "Smokey... ¡Tenía razón, todo el tiempo! Tenia que ser Smokey!",
  ui_story_31120601_55_dialog_content = "¡Ah, no esperaba menos de un famoso cazarrecompensas como tú! ¿Ya conoces la identidad del ladrón fantasma?",
  ui_story_31120601_56_dialog_content = "Ejem... no podemos estar absolutamente seguros todavía, ¿verdad? ¿Alguna vez lograste ver la cara de la persona?",
  ui_story_31120601_57_dialog_content = "La noche estaba oscura, así que no pude ver su rostro... Pero a juzgar por su voz, estoy seguro de que el ladrón era una mujer.",
  ui_story_31120601_58_dialog_content = "¿Y qué dijo ella exactamente?",
  ui_story_31120601_59_dialog_content = "Dentro de tres días, al dar las doce...",
  ui_story_31120601_60_dialog_content = "Volveré para llevarme la piedra preciosa.",
  ui_story_31120601_61_dialog_content = "¿Quién eres?",
  ui_story_31120601_62_dialog_content = "Creo que dejé una firma en mi tarjeta de visita.",
  ui_story_31120601_63_dialog_content = "<color=#FFB400>\"Gato negro\"</color>? Pero ese no puede ser tu verdadero nombre, ¿verdad?",
  ui_story_31120601_64_dialog_content = "En respuesta, hizo un sonido impaciente y burlón, y al momento siguiente... ¡desapareció justo ante mis ojos, como un susurro en el viento!",
  ui_story_31120601_65_dialog_content = "Por desgracia... Fue en ese momento que supe que este ladrón fantasma hablaba en serio.",
  ui_story_31120601_66_dialog_content = "Bueno, ese tipo de actitud SÍ suena como—",
  ui_story_31120601_67_dialog_content = "Smokey!",
  ui_story_31120601_68_dialog_content = "Si cree que destruir evidencia me sacará de su rastro, tiene otra cosa por venir.",
  ui_story_31120601_69_dialog_content = "Lo juro, Smokey estará a merced de mi látigo al final del día!",
  ui_story_31120601_69X_dialog_content = "¡Me gustaría ver a ese alocado Señor de las Sombras intentar salvarla de mi ira!",
  ui_story_31120601_70_dialog_content = "Sin embargo, ¿no crees que este comportamiento es demasiado descarado?",
  ui_story_31120601_71_dialog_content = "¿Enviar tantas tarjetas telefónicas por correo y luego irrumpir en la casa del tasador solo para destruir pruebas?",
  ui_story_31120601_72_dialog_content = "¿No hubiera sido más fácil simplemente robar la piedra preciosa?",
  ui_story_31120601_73_dialog_content = "Hmph, ese es el tipo de monstruo sin corazón y condescendiente que es. Nunca está satisfecha a menos que involucre a tantas personas como sea posible en sus travesuras.",
  ui_story_31120601_74_dialog_content = "¿De verdad crees eso?",
  ui_story_31120601_75_dialog_content = "Ella siempre ha sido así.",
  ui_story_31120601_76_dialog_content = "¡Pero está totalmente equivocada si cree que se irá riendo hoy!",
  ui_story_31120601_77_dialog_content = "Escucharte decir estas palabras me trae un gran alivio.",
  ui_story_31120601_78_dialog_content = "Mira, aquí está la piedra preciosa que el ladrón fantasma ha puesto en su mira.",
  ui_story_31120601_79_dialog_content = "Guau... ¡Qué hermoso diamante!",
  ui_story_31120601_80_dialog_content = "¡Jajaja! ¡Ay, esto no es un simple diamante!",
  ui_story_31120601_81_dialog_content = "Es más duro que cualquier diamante, más duradero que el oro y más brillante que las auroras de Northland. Es la piedra preciosa más valiosa que existe en la actualidad.",
  ui_story_31120601_82_dialog_content = "No hay más que uno de su tipo en todo el mundo.",
  ui_story_31120601_83_dialog_content = "Ya veo... Con razón el ladrón fantasma lo persigue.",
  ui_story_31120601_84_dialog_content = "Justo ahora estaba pensando para mí mismo, con todas las gemas valiosas en tu casa...",
  ui_story_31120601_85_dialog_content = "¿Por qué estás tan seguro de que el ladrón fantasma estaba apuntando a este?",
  ui_story_31120601_86_dialog_content = "...",
  ui_story_31120601_87_dialog_content = "Parece que el valor total de todas las demás piezas de su colección no se acercaría al valor de esta piedra preciosa.",
  ui_story_31120601_88_dialog_content = "Sí, sí, eso es todo.",
  ui_story_31120601_89_dialog_content = "¡Ahora bien, dejaré el resto en tus capaces manos!",
  ui_story_31120601_90_dialog_content = "No nos queda mucho tiempo, así que prepárate.",
  ui_story_31120601_91_dialog_content = "Lo diré una vez más: el momento en que sientes Smokey¡Tienes que decirme exactamente dónde está!",
  ui_story_31120601_92_dialog_content = "Pero, ¿realmente podemos hacerlo...? ¿Solo nosotros dos?",
  ui_story_31120601_93_dialog_content = "¿De verdad crees que estamos solos? Mis fans están esperando afuera, listos para una emboscada. Smokey ¡en cualquier momento dado!",
  ui_story_31120601_94_dialog_content = "<color=#e8d9bb>Gong... Gong... Gong...</color>",
  ui_story_31120601_95_dialog_content = "Ya es pasada la medianoche... ¿Por qué no está aquí todavía?",
  ui_story_31120601_96_dialog_content = "Shhh...",
  ui_story_31120601_97_dialog_content = "¡Ella está aquí! ¡Afuera de la ventana!",
  ui_story_31120601_98_dialog_content = "<color=#e8d9bb>*vidrio roto*</color>",
  ui_story_31120601_98X_dialog_content = "Smokey! ¡No creas que puedes irrumpir y entrar!",
  ui_story_31120601_99_dialog_content = "Parece que tus fans no pudieron detener al ladrón...",
  ui_story_31120601_100_dialog_content = "Mmm... ¿Qué está pasando? ¡No hay nadie fuera de la ventana!",
  ui_story_31120601_101_dialog_content = "¿Eh? D-Déjame intentarlo de nuevo.",
  ui_story_31120601_102_option_content = "Usa la habilidad psíquica",
  ui_story_31120601_103_dialog_content = "Oh, no... ¡El ladrón ya está en la puerta!",
  ui_story_31120601_103X_dialog_content = "Entonces, ¿cuál fue el punto de romper la ventana justo ahora...?",
  ui_story_31120601_104_dialog_content = "¿Una distracción... tal vez? ¡Me quedaré junto a la puerta! ¡Veamos cómo me supera ahora!",
  ui_story_31120601_105_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_31120601_106_dialog_content = "¡Ah!",
  ui_story_31120601_107_dialog_content = "Genevieve! ¿Estás... estás bien?",
  ui_story_31120601_108_dialog_content = "Muévete del camino, PlayerName!",
  ui_story_31120601_109_dialog_content = "¡Prueba esto! ¡Prender fuego!",
  ui_story_31120601_110_dialog_content = "¡Decir ah! ¡Arde bebe arde!",
  ui_story_31120601_111_dialog_content = "¡Eso estuvo cerca! Casi me quemo. Pero ese ataque de hace un momento...",
  ui_story_31120601_112_dialog_content = "Smokey... ¡Sabía que eras tú todo el tiempo!",
  ui_story_31120601_113_dialog_content = "Jaja, es más animado aquí de lo que esperaba.",
  ui_story_31120601_114_dialog_content = "Incluso tú decidiste unirte a la diversión, PlayerName?",
  ui_story_31120601_115_option_content = "Sí...",
  ui_story_31120601_116_dialog_content = "Más precisamente, me arrastraron a eso.",
  ui_story_31120601_117_option_content = "Por favor, no malinterpretes...",
  ui_story_31120601_118_dialog_content = "Realmente no tenía elección...",
  ui_story_31120601_119_dialog_content = "¡Las cosas se están poniendo interesantes!",
  ui_story_31120601_120_dialog_content = "¡Oye! ¡Cómo te atreves a ignorarme!",
  ui_story_31120601_121_dialog_content = "¡Quema!",
  ui_story_31120601_122_dialog_content = "¡Quédate abajo!",
  ui_story_31120601_123_dialog_content = "Honestamente... Nunca esperé que me persiguieras hasta aquí, Ginny.",
  ui_story_31120601_124_dialog_content = "G-Ginny?",
  ui_story_31120601_125_dialog_content = "¿Quién dijo que podías llamarme así?",
  ui_story_31120601_126_dialog_content = "Caray, ¿te importa mantenerlo bajo? Tu voz me da dolores de cabeza.",
  ui_story_31120601_127_dialog_content = "Además, no es mi culpa que tu nombre sea tan largo. Simplemente no tengo ganas de decir todo el asunto cada vez.",
  ui_story_31120601_128_dialog_content = "Entonces, esos debiluchos afuera... ¿Los dejaste afuera para mí, solo para que pudiera hacer un buen calentamiento?",
  ui_story_31120601_129_dialog_content = "¿Ginnyviese?",
  ui_story_31120601_130_dialog_content = "Es Genevieve!!!",
  ui_story_31120601_131_dialog_content = "¿Estabas tratando de imitar mis ataques?",
  ui_story_31120601_132_dialog_content = "Estás bromeando, ¿verdad? ¿Habéis olvidado que mi talento para la Luminática se manifestó primero?",
  ui_story_31120601_133_dialog_content = "¿Vaya? ¿Es así como sucedió?",
  ui_story_31120601_134_dialog_content = "Smokey sigue esquivando todo GenevieveLos ataques de en el momento justo...",
  ui_story_31120601_135_dialog_content = "¡Y mientras tanto, ella sigue acercándose más y más a la vitrina de la gema!",
  ui_story_31120601_136_dialog_content = "Ni te lo pienses!!!",
  ui_story_31120601_137_dialog_content = "¿Qué tal si intentas detenerme entonces?",
  ui_story_31120601_138_dialog_content = "¿Por qué tienes que ser así?...",
  ui_story_31120601_139_dialog_content = "¡¿Por qué insistes en este comportamiento criminal imprudente?!",
  ui_story_31120601_140_dialog_content = "¿Por qué te encanta meter la nariz en los asuntos de otras personas también?",
  ui_story_31120601_141_dialog_content = "¡¿P-Crees que solo estoy siendo entrometido?! Siempre... siempre te he admirado como alguien a quien superar algún día...",
  ui_story_31120601_142_dialog_content = "¡Pero mira en lo que te has convertido!",
  ui_story_31120601_143_dialog_content = "no eres el Smokey Solía saber... Ya no.",
  ui_story_31120601_144_dialog_content = "Oi, tal vez olvidé mencionarlo, pero hoy soy \"Black Cat\", no Smokey.",
  ui_story_31120601_145_dialog_content = "Si es así... Entonces no tengo motivos para contenerme.",
  ui_story_31120601_146_dialog_content = "¡Ríndanse!",
  ui_story_31120601_147_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_31120601_148_dialog_content = "¡Q-Qué llama tan enorme!",
  ui_story_31120601_149_dialog_content = "mi gema...",
  ui_story_31120601_150_dialog_content = "No te preocupes, estaba un paso por delante de ella y logré agarrar tu gema antes que ella.",
  ui_story_31120601_151_dialog_content = "Ver-",
  ui_story_31120601_152_dialog_content = "E-Espera... Genevieve¡¿Quemaste la piedra preciosa?!",
  ui_story_31120601_153_dialog_content = "¡¿Qué habéis hecho, tontos?! ¡Te contraté para proteger la piedra, no para destruirla!",
  ui_story_31120601_154_dialog_content = "Yo...",
  ui_story_31120601_155_dialog_content = "Lo siento...",
  ui_story_31120601_156_dialog_content = "Jajaja, interesante.",
  ui_story_31120601_157_dialog_content = "No me había divertido tanto en mucho tiempo.",
  ui_story_31120601_158_dialog_content = "Smokey! ¿Es este otro de tus trucos?",
  ui_story_31120601_159_dialog_content = "¿Todavía no lo entienden? La piedra que convertiste en ceniza ni siquiera era real.",
  ui_story_31120601_160_dialog_content = "¡M-mentiroso!",
  ui_story_31120601_161_dialog_content = "¡Era mi posesión más rara y preciosa!",
  ui_story_31120601_162_dialog_content = "Oh realmente ahora.",
  ui_story_31120601_163_dialog_content = "La piedra preciosa que robaste no se quemaría tan fácilmente, ¿no crees?",
  ui_story_31120601_164_dialog_content = "\"Robó\"? ¿De qué estás hablando?",
  ui_story_31120601_165_dialog_content = "El verdadero dueño de esta piedra preciosa no es este hombre aquí.",
  ui_story_31120601_166_dialog_content = "¡Dámelo!",
  ui_story_31120601_167_dialog_content = "Por favor... No puedes... ¡Por favor, no me quites esta gema! Es todo lo que me queda para recordar a mi madre por...",
  ui_story_31120601_168_dialog_content = "Algo como esto nunca tendrá ningún valor en manos como las tuyas, muchacho.",
  ui_story_31120601_169_dialog_content = "Tenga la seguridad de que lo cuidaré muy bien.",
  ui_story_31120601_171_dialog_content = "... Cuidado, chico.",
  ui_story_31120601_172_dialog_content = "¡Oye, vamos a escuchar otro de los cuentos de la abuela!",
  ui_story_31120601_172X_dialog_content = "¡Escuché que hoy hablarán sobre el ladrón fantasma!",
  ui_story_31120601_172X1_dialog_content = "¿Mmm? ¿De qué están hablando esos dos niños?",
  ui_story_31120601_173_dialog_content = "Adelante... Me pondré al día con todos en un momento.",
  ui_story_31120601_174_dialog_content = "¡No tardes demasiado!",
  ui_story_31120601_175_dialog_content = "Ladrones fantasmas... Si tan solo fueran reales...",
  ui_story_31120601_176_dialog_content = "Entonces tal vez uno de ellos podría ayudarme a recuperar la piedra preciosa que mi mamá me dejó... Si tan solo...",
  ui_story_31120601_177_dialog_content = "Ladrón fantasma, ¿eh?",
  ui_story_31120601_178_dialog_content = "Suena bastante interesante.",
  ui_story_31120601_179_dialog_content = "Espera, entonces, ¿ustedes no sabían?",
  ui_story_31120601_180_dialog_content = "Y yo que pensaba que al menos habías echado un vistazo a las tarjetas de visita que te envié.",
  ui_story_31120601_181_dialog_content = "Mencioné que si le devolvieran la piedra a ese chico, no tendría que venir aquí en persona por ella.",
  ui_story_31120601_182_dialog_content = "¿Pero no quemaste las tarjetas de visita?",
  ui_story_31120601_183_dialog_content = "¿Eh? No me tomes como chivo expiatorio por cosas que no hice.",
  ui_story_31120601_184_dialog_content = "Entonces eso solo deja otra posibilidad...",
  ui_story_31120601_185_dialog_content = "Sr. Tasador, los quemó, ¿no?",
  ui_story_31120601_186_dialog_content = "¿Q-Qué prueba tienes?",
  ui_story_31120601_187_dialog_content = "... Ninguno por el momento, lamentablemente.",
  ui_story_31120601_188_dialog_content = "Pero quienquiera que los quemó definitivamente lo hizo para encubrir su crimen.",
  ui_story_31120601_189_dialog_content = "Siempre podríamos ir a buscar a ese chico y preguntarle si perdió una piedra preciosa...",
  ui_story_31120601_190_dialog_content = "Ja... ¡Jajaja! ¡Entiendo ahora!",
  ui_story_31120601_191_dialog_content = "Ustedes dos desgraciados han estado en connivencia con este \"Gato Negro\" todo el tiempo, ¿no es así?",
  ui_story_31120601_192_dialog_content = "Ahora que lo han destruido, ¿cómo planean pagarme por ello?",
  ui_story_31120601_193_dialog_content = "Uf, qué dolor... Odio cuando los asquerosos como tú se niegan a admitir la derrota.",
  ui_story_31120601_194_dialog_content = "Tenías miedo de que robara la piedra preciosa real, así que la reemplazaste con esa falsificación.",
  ui_story_31120601_195_dialog_content = "De esa forma, si le robaban la falsificación, no perdería nada de valor.",
  ui_story_31120601_196_dialog_content = "Y si fue destruido por alguna razón, podría echarnos la culpa.",
  ui_story_31120601_197_dialog_content = "Ja, qué plan tan meticulosamente diseñado.",
  ui_story_31120601_198_dialog_content = "¡Mentiras! ¡Mentiras y calumnias!",
  ui_story_31120601_199_dialog_content = "Si todavía no estás dispuesto a confesarte, ¿qué tal si vamos a pagar el Istvan Pandilla una visita juntos?",
  ui_story_31120601_200_dialog_content = "Istvan...",
  ui_story_31120601_201_dialog_content = "La gente de Umbraton dice que es bueno con este tipo de asuntos.",
  ui_story_31120601_202_dialog_content = "Ah, pero tú lo sabrías mejor que yo, ¿verdad? Después de todo, tú también eres residente de Umbraton.",
  ui_story_31120601_203_dialog_content = "...",
  ui_story_31120601_204_dialog_content = "¿Dónde has escondido la verdadera piedra preciosa?",
  ui_story_31120601_205_dialog_content = "¡...!",
  ui_story_31120601_206_dialog_content = "¡¡¡Se ha ido!!!",
  ui_story_31120601_207_dialog_content = "¡Basta de tus trucos! ¡Dinos dónde está!",
  ui_story_31120601_208_dialog_content = "¡Yo... estoy diciendo la verdad! Estuvo en mi bolsillo todo este tiempo... ¡Pero ahora no puedo encontrarlo!",
  ui_story_31120601_209_dialog_content = "¡Escúpelo!",
  ui_story_31120601_210_dialog_content = "¡¿Dónde está la verdadera piedra preciosa, ladrón?!",
  ui_story_31120601_211_dialog_content = "Oh, deja de malgastar tu aliento con él.",
  ui_story_31120601_212_dialog_content = "Smokey...",
  ui_story_31120601_213_dialog_content = "Espera, ¿a dónde fue?",
  ui_story_31120601_214_dialog_content = "ella es...",
  ui_story_31120601_215_dialog_content = "¡Ella está por ahí! ¡En el techo frente a nosotros!",
  ui_story_31120601_216_dialog_content = "¿Pero cómo? Ella estaba en la habitación hace un segundo...",
  ui_story_31120601_217_dialog_content = "¿Por qué estás tan sorprendido?",
  ui_story_31120601_218_dialog_content = "Oh ya entiendo.",
  ui_story_31120601_219_dialog_content = "No tienes sentido de la imaginación, por eso no puedes descifrar las cosas.",
  ui_story_31120601_220_dialog_content = "¡¿Cómo te atreves a burlarte de mí otra vez?!",
  ui_story_31120601_221_dialog_content = "Estos son solo hechos.",
  ui_story_31120601_222_dialog_content = "Espera, ¿es esa... la verdadera piedra preciosa que tienes en las manos?",
  ui_story_31120601_223_dialog_content = "Te tomó mucho tiempo darte cuenta.",
  ui_story_31120601_224_dialog_content = "Hombre, esto es aburrido.",
  ui_story_31120601_225_dialog_content = "Me voy de aquí y me llevo esto.",
  ui_story_31120601_226_dialog_content = "Hasta la próxima.",
  ui_story_31120601_227_dialog_content = "<size=50>¡¡¡E-Espera!!!</size>",
  ui_story_31120601_228_dialog_content = "<color=#e8d9bb>Whoosh——</color>",
  ui_story_31120601_229_dialog_content = "Ella se ha ido...",
  ui_story_31120601_230_dialog_content = "...",
  ui_story_31120601_231_dialog_content = "¿Por qué me siento tan vacío, de repente?",
  ui_story_31120601_232_dialog_content = "...",
  ui_story_31120601_233_dialog_content = "¿Qué hacemos ahora?",
  ui_story_31120601_234_dialog_content = "Llevar al perpetrador ante la justicia, por supuesto.",
  ui_story_31120601_235_dialog_content = "Pero Smokeyya se fue hace mucho...",
  ui_story_31120601_236_dialog_content = "Estoy hablando del tasador de gemas. Lo que venga después es para el Istvan Pandilla para decidir.",
  ui_story_31120601_237_dialog_content = "Pero la piedra preciosa...",
